string D="ArtSource/Pipeline/Review/BriarwickEnvironment02";var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.path!="Assets/Scenes/Briarwick_Hamlet_Dev01.unity"||s.isDirty||EditorApplication.isPlaying)throw new System.Exception("Saved Briarwick Edit only");
string Path(Transform t){return t.parent==null?t.name:Path(t.parent)+"/"+t.name;}
var snapshot=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Select(t=>new{path=Path(t),active=t.gameObject.activeSelf,components=t.GetComponents<Component>().Where(c=>c!=null).Select(c=>new{type=c.GetType().FullName,json=EditorJsonUtility.ToJson(c)}).ToArray()}).ToArray();System.IO.File.WriteAllText(D+"/SceneBefore.json",Newtonsoft.Json.JsonConvert.SerializeObject(snapshot));
var terrain=Terrain.activeTerrain;var height=terrain.terrainData.GetHeights(0,0,terrain.terrainData.heightmapResolution,terrain.terrainData.heightmapResolution);System.IO.File.WriteAllBytes(D+"/HeightBefore.bin",height.Cast<float>().SelectMany(v=>System.BitConverter.GetBytes(v)).ToArray());
var prefabs=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/TerrainSampleAssets/Prefabs"}).Select(g=>{var p=AssetDatabase.GUIDToAssetPath(g);var go=AssetDatabase.LoadAssetAtPath<GameObject>(p);return new{path=p,triangles=go.GetComponentsInChildren<MeshFilter>(true).Sum(f=>f.sharedMesh.triangles.Length/3),bounds=go.GetComponent<MeshFilter>().sharedMesh.bounds.ToString(),materials=go.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Select(m=>new{m.name,shader=m.shader.name,supported=m.shader.isSupported}).ToArray(),dependencies=AssetDatabase.GetDependencies(p,true)};}).ToArray();
var textures=AssetDatabase.FindAssets("t:Texture2D",new[]{"Assets/TerrainSampleAssets/Textures"}).Select(g=>{var p=AssetDatabase.GUIDToAssetPath(g);var t=AssetDatabase.LoadAssetAtPath<Texture2D>(p);var ti=(TextureImporter)AssetImporter.GetAtPath(p);return new{path=p,t.width,t.height,format=t.format.ToString(),ti.maxTextureSize,ti.sRGBTexture,type=ti.textureType.ToString(),runtimeBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t)};}).ToArray();
var layers=AssetDatabase.FindAssets("t:TerrainLayer",new[]{"Assets/TerrainSampleAssets/TerrainLayers"}).Select(g=>{var p=AssetDatabase.GUIDToAssetPath(g);var l=AssetDatabase.LoadAssetAtPath<TerrainLayer>(p);return new{path=p,diffuse=AssetDatabase.GetAssetPath(l.diffuseTexture),normal=AssetDatabase.GetAssetPath(l.normalMapTexture),mask=AssetDatabase.GetAssetPath(l.maskMapTexture),tile=l.tileSize.ToString()};}).ToArray();var result=new{prefabs,layers,textures,terrain=new{path=AssetDatabase.GetAssetPath(terrain.terrainData),size=terrain.terrainData.size.ToString(),terrain.terrainData.alphamapResolution,shader=terrain.materialTemplate.shader.name}};System.IO.File.WriteAllText(D+"/PackageInspection.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return new{prefabs=prefabs.Length,layers=layers.Length,textures=textures.Length,textureSizes=textures.GroupBy(t=>t.width+"x"+t.height+" "+t.format).Select(g=>new{size=g.Key,count=g.Count()}).ToArray(),loadedTextureBytes=textures.Sum(t=>t.runtimeBytes)};
